'use client';

import { useQueryClient } from '@tanstack/react-query';
import { ArrowLeft, LogOut, ShieldCheck } from 'lucide-react';
import Link from 'next/link';
import { usePathname, useRouter } from 'next/navigation';
import { useEffect, type ReactNode } from 'react';
import { Logo } from '@/components/shell/logo';
import { ThemeMenu } from '@/components/shell/topbar';
import { Button } from '@/components/ui/button';
import { EmptyState, ErrorState, LoadingState } from '@/components/ui/states';
import { useToast } from '@/components/ui/toast';
import { ApiError, post } from '@/lib/api/client';
import { cn } from '@/lib/cn';
import { useMe } from '@/lib/session';

const NAV = [
  { href: '/admin', label: 'Overview' },
  { href: '/admin/orgs', label: 'Organizations' },
  { href: '/admin/users', label: 'Users' },
];

/**
 * The platform admin area (Octopi Digital staff). It needs no organization; it shows only for a
 * super admin (`platformRole` on GET /v1/me). Everyone else sees "not found", like the API answers.
 */
export function AdminShell({ children }: { children: ReactNode }) {
  const me = useMe();
  const router = useRouter();
  const pathname = usePathname();
  const client = useQueryClient();
  const toast = useToast();
  const unauthenticated = me.error instanceof ApiError && me.error.status === 401;

  useEffect(() => {
    if (unauthenticated) router.replace(`/login?next=${encodeURIComponent(pathname)}`);
  }, [unauthenticated, router, pathname]);

  if (me.isPending || unauthenticated) {
    return (
      <div className="mx-auto max-w-md px-4 py-24">
        <LoadingState label="Loading…" rows={2} />
      </div>
    );
  }
  if (me.isError) {
    return (
      <div className="mx-auto max-w-md px-4 py-24">
        <ErrorState error={me.error} title="Could not load your account" onRetry={() => void me.refetch()} />
      </div>
    );
  }
  if (me.data.platformRole !== 'super_admin') {
    return (
      <main id="main" className="mx-auto max-w-lg px-4 py-24">
        <EmptyState title="Page not found" description="This page does not exist, or your account cannot open it." action={<Button onClick={() => router.replace('/')}>Go to the dashboard</Button>} />
      </main>
    );
  }

  const active = (href: string) => (href === '/admin' ? pathname === '/admin' : pathname === href || pathname.startsWith(`${href}/`));
  return (
    <div className="flex min-h-dvh flex-col">
      <a href="#main" className="sr-only z-50 rounded-md bg-surface px-3 py-2 text-sm font-medium text-text focus:not-sr-only focus:fixed focus:top-2 focus:left-2">
        Skip to main content
      </a>
      <header className="sticky top-0 z-30 border-b border-border bg-surface/95 backdrop-blur">
        <div className="mx-auto flex h-14 max-w-7xl items-center gap-3 px-4 sm:px-6 lg:px-8">
          <Logo compact />
          <span className="inline-flex items-center gap-1 rounded-full border border-accent/40 bg-accent-soft px-2 py-0.5 text-xs font-semibold text-accent-text">
            <ShieldCheck aria-hidden="true" className="size-3.5" />
            Platform admin
          </span>
          <div className="ml-auto flex items-center gap-1">
            <Link href="/" className="hidden h-9 items-center gap-1 rounded-md px-3 text-sm font-medium text-text hover:bg-surface-2 sm:inline-flex">
              <ArrowLeft aria-hidden="true" className="size-4" />
              Dashboard
            </Link>
            <ThemeMenu />
            <Button
              variant="ghost"
              size="sm"
              aria-label="Sign out"
              onClick={async () => {
                try {
                  await post('/v1/auth/logout');
                } catch (error) {
                  toast.error('Could not sign out', error);
                  return;
                }
                client.clear();
                router.replace('/login');
              }}
            >
              <LogOut aria-hidden="true" />
            </Button>
          </div>
        </div>
        <nav aria-label="Platform admin" className="mx-auto flex max-w-7xl gap-1 overflow-x-auto px-4 sm:px-6 lg:px-8">
          {NAV.map((item) => (
            <Link
              key={item.href}
              href={item.href}
              aria-current={active(item.href) ? 'page' : undefined}
              className={cn('-mb-px inline-flex h-10 shrink-0 items-center border-b-2 px-3 text-sm font-medium', active(item.href) ? 'border-accent text-text' : 'border-transparent text-muted hover:text-text')}
            >
              {item.label}
            </Link>
          ))}
        </nav>
      </header>
      <main id="main" tabIndex={-1} className="flex-1 outline-none">
        {children}
      </main>
    </div>
  );
}
